#!/usr/bin/env bash
# Terminal-Bench 2.0 evaluation with the PAPER'S OWN harness (Vanillux2Agent).
#
#   MODEL_LABEL=base ARM_MODEL=qwen3-8b       bash scripts/eval_tb2_vanillux.sh
#   MODEL_LABEL=sft  ARM_MODEL=qwen3-8b-sft   bash scripts/eval_tb2_vanillux.sh
#
# Extra arguments are forwarded to `harbor run`.
#
# ===========================================================================
# WHY NOT terminus-2 — this is the whole point of the file
# ===========================================================================
# The SFT data is generated by tmax's vanillux harness. Vanillux2Agent imports
# _SYSTEM_TEMPLATE and SUBMIT_MARKER ("COMPLETE_TASK_AND_SUBMIT_FINAL_OUTPUT")
# from rl_data/generator/, i.e. the eval prompt is the SAME STRING the model was
# fine-tuned on. terminus-2 is a different action protocol (raw keystrokes).
#
# Paper §C: "our harness and mini-SWE-agent outperform Terminus-2 [...] we
# attribute this drop to more complex tool formats [...] especially difficult
# for smaller models to follow." Table 5, Qwen3.5-9B on TB Lite:
#   mini-SWE-agent 44.1 | tmax harness 41.9 | Terminus-2 36.4 | OpenHands 36.0
# Figure 1, the source of the 1.1 -> 6.0 expectation for Qwen3-8B, reports
# "scores using our simple harness" — not Terminus-2.
#
# The three baseline runs in ~/tb2-eval/jobs (2026-09-17/18) used terminus-2.
# They are NOT a valid comparison point for a run made with this script: the
# harness delta is ~5-8 points, larger than the effect being measured. Both
# arms must be re-measured here.
#
# Harbor 0.23.0 note: tmax's README shows `--agent-import-path`, which that
# version no longer has — a custom agent goes through `--agent` as
# module.path:ClassName. Harbor also ships a built-in `mini-swe-agent`, the
# harness that scores highest in the paper's Table 5 (44.1); it is a reasonable
# cross-check, but Vanillux2Agent is the one the SFT data was generated with.
# ===========================================================================
#
# ===========================================================================
# SERVE THE MODEL FIRST, IN A SECOND SHELL — with tool calling ENABLED
# ===========================================================================
# Vanillux2Agent passes tools=TOOL_SCHEMAS to litellm and reads
# response_msg["tool_calls"]. Without server-side tool parsing every turn is a
# format error and the score is a measurement of the serving flags, not of the
# model. The `qwen3` container used for the terminus-2 baseline does NOT have
# these flags.
#
#   # baseline arm
#   vllm serve /models/Qwen3-8B --served-model-name qwen3-8b \
#       --dtype bfloat16 --gpu-memory-utilization 0.5 --port 8888 \
#       --enable-auto-tool-choice --tool-call-parser qwen3_xml
#
#   # sft arm — same flags, different weights
#   vllm serve <checkpoint> --served-model-name qwen3-8b-sft \
#       --dtype bfloat16 --gpu-memory-utilization 0.5 --port 8888 \
#       --enable-auto-tool-choice --tool-call-parser qwen3_xml
#
# Both arms must be served with IDENTICAL flags. Run them back to back: two
# terminus-2 runs 24 h apart already solved a disjoint set of tasks.
# ===========================================================================

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TMAX_DIR="${TMAX_DIR:-$HOME/tmax}"
TB_REPO="${TB_REPO:-$HOME/Desktop/terminal-bench-2.0}"
JOBS_DIR="${JOBS_DIR:-$HOME/tb2-eval/jobs}"

# --- The two arms ---------------------------------------------------------
# ARM_MODEL is the --served-model-name given to vLLM; MODEL_LABEL only names
# the job directory. Everything else MUST be identical between the two arms.
MODEL_LABEL="${MODEL_LABEL:?set MODEL_LABEL=base or MODEL_LABEL=sft}"
ARM_MODEL="${ARM_MODEL:?set ARM_MODEL to the vLLM --served-model-name}"

# --- Attempts per task — OPEN DECISION (D-07), read before changing -------
# K=1 on 89 tasks resolves only a jump to ~15%. The paper expects 1.1 -> 6.0,
# which at K=1 stays inside the noise: 3/89 has a 95% CI of [0.7%, 9.5%].
# tmax's own eval example uses -k 5. Cost at ~7 h per pass:
#   K=1 -> ~7 h/arm   (~14 h both)  directional only
#   K=5 -> ~35 h/arm  (~3 days both) matches the paper's protocol
# Decide this BEFORE the run, not after seeing the number.
K="${K:-1}"

ENDPOINT="${ENDPOINT:-http://localhost:8888/v1}"
N_CONCURRENT="${N_CONCURRENT:-16}"
# 8, not the default: at 3.5 the 2026-09-18 run lost 22/66 trials to
# AgentTimeoutError while healthy. See ~/tb2-eval/run_eval.sh for the analysis.
TIMEOUT_MULT="${TIMEOUT_MULT:-8}"
# The paper's own invocation passes this; the rest of Vanillux2Agent's defaults
# (max_steps 64, temperature 0.7, top_p 0.95, max_tokens 16384) are the paper's
# and are deliberately NOT overridden here.
MAX_FORMAT_ERRORS="${MAX_FORMAT_ERRORS:-64}"

STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
JOB_NAME="${JOB_NAME:-vanillux2-${MODEL_LABEL}-k${K}-${STAMP}}"

export OPENAI_BASE_URL="$ENDPOINT"
export OPENAI_API_KEY="${OPENAI_API_KEY:-dummy}"
export PATH="$HOME/.local/bin:$PATH"

# --- Guards ---------------------------------------------------------------
if [[ "$(uname -s)" != "Linux" ]] || ! command -v nvidia-smi >/dev/null 2>&1; then
    echo "error: not the Spark (need Linux + nvidia-smi)." >&2; exit 1
fi
command -v harbor >/dev/null || { echo "error: harbor not on PATH." >&2; exit 1; }
[[ -d "$TB_REPO" ]] || { echo "error: Terminal-Bench 2.0 not at $TB_REPO" >&2; exit 1; }
[[ -d "$TMAX_DIR/Vanillux2Agent" ]] || {
    echo "error: Vanillux2Agent not found at $TMAX_DIR/Vanillux2Agent" >&2
    echo "       set TMAX_DIR to your clone of https://github.com/hamishivi/tmax" >&2; exit 1; }

# The agent must import inside the interpreter HARBOR runs on, which is not the
# system python: harbor is a uv tool install with its own site-packages.
HARBOR_PY="$(head -1 "$(command -v harbor)" | sed 's|^#!||')"
echo "harbor interpreter: $HARBOR_PY"
if ! PYTHONPATH="$TMAX_DIR" "$HARBOR_PY" -c "from Vanillux2Agent import Vanillux2Agent" 2>/dev/null; then
    echo "error: Vanillux2Agent does not import under $HARBOR_PY." >&2
    echo "       it needs tmax on PYTHONPATH plus litellm in harbor's env:" >&2
    echo "       uv pip install --python \"$HARBOR_PY\" litellm" >&2; exit 1
fi

# The bash tool description the agent advertises must be the one the model was
# trained on. tmax resolves it from <tmax>/sft/preprocessing/config, a directory
# it never ships, and silently falls back to _DEFAULT_TOOL_SCHEMAS, which says
# commands run "in a new subshell" where the SFT data says "in a persistent
# shell". Opposite claims about whether cd and export survive a turn. See
# patches/tmax-harness-config/README.md.
EXPECTED_SCHEMA="$REPO_ROOT/patches/tmax-harness-config/tool_schemas.json"
if ! PYTHONPATH="$TMAX_DIR" "$HARBOR_PY" - "$EXPECTED_SCHEMA" <<'PYCHECK'
import json, sys
from rl_data.generator.sample_solutions import TOOL_SCHEMAS
expected = json.load(open(sys.argv[1]))
if TOOL_SCHEMAS != expected:
    got = TOOL_SCHEMAS[0]["function"]["description"] if TOOL_SCHEMAS else "<empty>"
    want = expected[0]["function"]["description"]
    print(f"  resolved: {got}\n  expected: {want}", file=sys.stderr)
    sys.exit(1)
PYCHECK
then
    echo "error: tmax resolves a bash tool schema the model was not trained on." >&2
    echo "       install the legacy harness config into the tmax checkout:" >&2
    echo "         mkdir -p \"$TMAX_DIR/sft/preprocessing/config\"" >&2
    echo "         cp $REPO_ROOT/patches/tmax-harness-config/tool_schemas.json \\" >&2
    echo "            $REPO_ROOT/patches/tmax-harness-config/system_prompt.txt \\" >&2
    echo "            \"$TMAX_DIR/sft/preprocessing/config/\"" >&2
    echo "       (if \$TMAX_DIR is not yours to write to, clone tmax yourself and" >&2
    echo "        point TMAX_DIR at your copy — do not evaluate without this.)" >&2
    exit 1
fi
echo "bash tool schema: matches the training data"

# amd64 emulation: task images are amd64-only, this box is aarch64, and binfmt
# registrations do not survive a reboot.
if [[ ! -e /proc/sys/fs/binfmt_misc/qemu-x86_64 ]]; then
    echo "registering qemu-x86_64 binfmt handler..."
    docker run --privileged --rm tonistiigi/binfmt --install amd64 >/dev/null || {
        echo "FATAL: could not register amd64 emulation" >&2; exit 1; }
fi

# harbor tool-install timeouts (same patch the terminus-2 runs used).
if [[ -f "$HOME/tb2-eval/patch_harbor.py" ]]; then
    python3 "$HOME/tb2-eval/patch_harbor.py" || { echo "FATAL: harbor patch failed" >&2; exit 1; }
fi

# Endpoint liveness AND that it serves the arm we think it does. On 2026-09-18 a
# stopped container burned 56 tasks with InternalServerError before anyone looked.
curl -sf -m 10 "$ENDPOINT/models" >/dev/null || {
    echo "FATAL: $ENDPOINT is down. Serve the model first (see header)." >&2; exit 1; }
if ! curl -sf -m 10 "$ENDPOINT/models" | grep -q "\"$ARM_MODEL\""; then
    echo "FATAL: $ENDPOINT does not serve '$ARM_MODEL'. It advertises:" >&2
    curl -sf -m 10 "$ENDPOINT/models" | grep -oE '"id":"[^"]+"' >&2
    echo "       ARM_MODEL must match vLLM's --served-model-name." >&2; exit 1; fi

# --- Provenance (AGENTS.md §5: an untracked run didn't happen) ------------
mkdir -p "$JOBS_DIR"
{
    echo "job_name:    $JOB_NAME"
    echo "started:     $(date -Is)"
    echo "arm:         $MODEL_LABEL  (served model: $ARM_MODEL)"
    echo "harness:     Vanillux2Agent (tmax $(git -C "$TMAX_DIR" rev-parse --short HEAD 2>/dev/null || echo unknown))"
    echo "dataset:     $TB_REPO"
    echo "attempts_k:  $K"
    echo "endpoint:    $ENDPOINT"
    echo "this repo:   $(git -C "$REPO_ROOT" rev-parse HEAD)"
    echo "extra args:  $*"
} > "$JOBS_DIR/$JOB_NAME.provenance.txt"

echo "=== TB2.0 / Vanillux2Agent — arm=$MODEL_LABEL model=$ARM_MODEL k=$K"
echo "    endpoint=$ENDPOINT concurrency=$N_CONCURRENT timeout_mult=$TIMEOUT_MULT"
echo "    results -> $JOBS_DIR/$JOB_NAME"
echo "REMINDER: is this running under tmux? It takes hours."
echo

cd "$TB_REPO"
PYTHONPATH="$TMAX_DIR" harbor run \
    -p . \
    --agent Vanillux2Agent:Vanillux2Agent \
    --model "openai/$ARM_MODEL" \
    --agent-kwarg api_base="$ENDPOINT" \
    --agent-kwarg max_format_errors="$MAX_FORMAT_ERRORS" \
    -k "$K" \
    -n "$N_CONCURRENT" \
    --timeout-multiplier "$TIMEOUT_MULT" \
    --agent-setup-timeout-multiplier 5 \
    -o "$JOBS_DIR" \
    --job-name "$JOB_NAME" \
    -y "$@" 2>&1 | tee "$JOBS_DIR/$JOB_NAME.console.log"

echo
echo "=== done: $JOBS_DIR/$JOB_NAME"
